glass.css:
:root {
  --bg-gradient: linear-gradient(135deg, #e0f2fe 0%, #c7d2fe 100%);
  --surface-bg: rgba(255, 255, 255, 0.72);
  --surface-border: rgba(255, 255, 255, 0.6);
  --text-primary: #1e293b;
  --text-secondary: #475569;
  --accent: #4f46e5;
  --radius: 16px;
}
.glass {
  background: var(--surface-bg);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--surface-border);
  border-radius: var(--radius);
  padding: 24px;
  color: var(--text-primary);
  box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.1);
}

frosted-dark.css:
:root {
  --surface-bg: rgba(15, 23, 42, 0.85);
  --surface-border: rgba(255, 255, 255, 0.12);
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --accent: #38bdf8;
  --radius: 12px;
}
.frosted-dark {
  background: var(--surface-bg);
  backdrop-filter: blur(16px);
  border: 1px solid var(--surface-border);
  border-radius: var(--radius);
  padding: 24px;
  color: var(--text-primary);
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
}

elevated.css:
:root {
  --surface-bg: #ffffff;
  --text-primary: #18181b;
  --text-secondary: #52525b;
  --accent: #2563eb;
  --radius: 12px;
  --shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.08);
}
.elevated {
  background: var(--surface-bg);
  border-radius: var(--radius);
  padding: 28px;
  color: var(--text-primary);
  box-shadow: var(--shadow);
}

bordered.css:
:root {
  --surface-bg: #ffffff;
  --text-primary: #0f172a;
  --text-secondary: #334155;
  --accent: #dc2626;
  --border-color: #0f172a;
}
.bordered {
  background: var(--surface-bg);
  border: 3px solid var(--border-color);
  border-radius: 6px;
  padding: 24px;
  color: var(--text-primary);
}

flat.css:
:root {
  --surface-bg: #f8fafc;
  --text-primary: #1e293b;
  --text-secondary: #475569;
  --accent: #0f766e;
}
.flat {
  background: var(--surface-bg);
  border-radius: 4px;
  padding: 24px;
  color: var(--text-primary);
}

glow.css:
:root {
  --surface-bg: #090a10;
  --text-primary: #ffffff;
  --text-secondary: #cbd5e1;
  --accent: #00f5d4;
  --glow-shadow: 0 0 18px rgba(0, 245, 212, 0.45);
}
.glow {
  background: var(--surface-bg);
  border: 1px solid var(--accent);
  border-radius: 12px;
  padding: 24px;
  color: var(--text-primary);
  box-shadow: var(--glow-shadow);
}

neumorphism.css:
:root {
  --surface-bg: #e2e8f0;
  --text-primary: #334155;
  --text-secondary: #64748b;
  --accent: #ea580c;
}
.neumorphism {
  background: var(--surface-bg);
  border-radius: 20px;
  padding: 30px;
  color: var(--text-primary);
  box-shadow: 8px 8px 16px #cbd5e1, -8px -8px 16px #ffffff;
}

paper.css:
:root {
  --surface-bg: #fdfbf7;
  --text-primary: #1c1917;
  --text-secondary: #44403c;
  --accent: #9a3412;
  --border-sepia: #d6d3d1;
}
.paper {
  background: var(--surface-bg);
  border: 1px solid var(--border-sepia);
  border-radius: 2px;
  padding: 32px;
  color: var(--text-primary);
  font-family: 'Hiragino Mincho ProN', 'Yu Mincho', 'Noto Serif JP', serif;
  box-shadow: 0 4px 10px rgba(0,0,0,0.06);
}
